import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Original probability/cost/effect bodies; WORLD companion queries and early frozen ownership only. */
public final class CompanionNegativeMethods {
 static final String P="local/lito381/server/",PC=P+"ClientSession",NEG=P+"NativeNegativeMaterialAction",H=P+"NativeCompanionNegative",TARGET=P+"NativeCompanionTargets";
 static AbstractInsnNode previous(AbstractInsnNode n){do{n=n.getPrevious();}while(n!=null&&n.getOpcode()<0);return n;}
 static ClassNode read(JarFile j,String name)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(name+".class"))).accept(c,ClassReader.SKIP_DEBUG);return c;}
 static byte[] bytes(ClassNode c){var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static MethodInsnNode call(String owner,String name,String desc){return new MethodInsnNode(INVOKESTATIC,owner,name,desc,false);}
 static MethodNode wrap(MethodNode m,String name){return new MethodNode(m.access,name,m.desc,m.signature,m.exceptions.toArray(String[]::new));}
 static void action(ClassNode c,MethodNode m){String old=m.name;m.name="nativeSceneOriginal"+Character.toUpperCase(old.charAt(0))+old.substring(1);var w=wrap(m,old);w.instructions.add(new VarInsnNode(ALOAD,0));w.instructions.add(new VarInsnNode(ALOAD,1));for(int n=0;n<4;n++)w.instructions.add(new VarInsnNode(n==3?ILOAD:ALOAD,n));var bootstrap=new Handle(H_INVOKESTATIC,"java/lang/invoke/LambdaMetafactory","metafactory","(Ljava/lang/invoke/MethodHandles$Lookup;Ljava/lang/String;Ljava/lang/invoke/MethodType;Ljava/lang/invoke/MethodType;Ljava/lang/invoke/MethodHandle;Ljava/lang/invoke/MethodType;)Ljava/lang/invoke/CallSite;",false);w.instructions.add(new InvokeDynamicInsnNode("run",m.desc.substring(0,m.desc.indexOf(')')+1)+"L"+P+"NativeSelfCastAction$Task;",bootstrap,Type.getMethodType("()V"),new Handle(H_INVOKESTATIC,NEG,m.name,m.desc,false),Type.getMethodType("()V")));w.instructions.add(call(H,"world","(L"+PC+";[BL"+P+"NativeSelfCastAction$Task;)V"));w.instructions.add(new InsnNode(RETURN));c.methods.add(w);}
 static void patch(ClassNode c){
  if(c.name.equals(P+"NativeWeaponBreakTargetLifecycle")){int ports=0;for(var m:c.methods)if(m.name.equals("captureOutput"))for(var n:m.instructions.toArray())if(n instanceof VarInsnNode v&&v.getOpcode()==ISTORE&&v.var==8){var add=new InsnList();add.add(new VarInsnNode(ILOAD,7));add.add(call(H,"objectPacket","(I)Z"));add.add(new VarInsnNode(ISTORE,8));m.instructions.insert(n,add);ports++;}if(ports!=1)throw new AssertionError("single target packet classification port");return;}
  if(c.name.equals(NEG)){int actions=0,owner=0,admit=0,bodies=0;for(var m:new ArrayList<>(c.methods)){
   for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode v&&v.owner.equals(PC)&&(v.name.equals("nativeMaterialEntangleBody")||v.name.equals("nativeMaterialEraseBody"))){m.instructions.set(v,call(H,v.name.equals("nativeMaterialEntangleBody")?"entangleBody":"eraseBody","(L"+PC+";"+v.desc.substring(1)));bodies++;}
   if(m.name.equals("entangle")||m.name.equals("erase")){action(c,m);actions++;}
   if(m.name.equals("owner")){var w=wrap(m,"owner");m.name="nativeSceneOriginalOwner";m.access&=~ACC_PRIVATE;w.instructions.add(new VarInsnNode(ALOAD,0));w.instructions.add(new VarInsnNode(LLOAD,1));w.instructions.add(call(H,"owner",m.desc));w.instructions.add(new InsnNode(ARETURN));c.methods.add(w);owner++;}
   if(m.name.equals("admit")){var w=wrap(m,"admit");m.name="nativeSceneOriginalAdmit";for(int i=0;i<6;i++)w.instructions.add(new VarInsnNode(i<3?ALOAD:ILOAD,i));w.instructions.add(call(H,"admit",m.desc));w.instructions.add(new InsnNode(IRETURN));c.methods.add(w);admit++;}
  }if(actions!=2||owner!=1||admit!=1||bodies!=2)throw new AssertionError("exact negative capture ports");return;}
  int roots=0,snapshots=0,iterators=0,gates=0;for(var m:c.methods)if(m.name.equals("nativeMaterialEntangleBody")||m.name.equals("nativeMaterialEraseBody")){
   roots++;for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode v&&v.owner.equals(PC)&&v.name.equals("classicWorldCompanionSnapshots")){
    if(!(previous(v) instanceof VarInsnNode owner&&owner.var==14))throw new AssertionError("owner slot");AbstractInsnNode store=v;while(store!=null&&!(store instanceof VarInsnNode s&&s.getOpcode()==ASTORE&&s.var==14))store=previous(store);if(store==null)throw new AssertionError("owner store");var cast=previous(store);var next=previous(cast);var load=previous(next);if(!(cast instanceof TypeInsnNode t&&t.desc.equals(PC)&&next instanceof MethodInsnNode nextCall&&nextCall.name.equals("next")&&load instanceof VarInsnNode l&&l.var==13))throw new AssertionError("original companion iterator");AbstractInsnNode iterator=load;while(iterator!=null&&!(iterator instanceof VarInsnNode s&&s.getOpcode()==ASTORE&&s.var==13))iterator=previous(iterator);if(iterator==null||!(previous(iterator) instanceof MethodInsnNode it&&it.owner.equals("java/util/List")&&it.name.equals("iterator")))throw new AssertionError("list iterator");var add=new InsnList();add.add(new VarInsnNode(ALOAD,0));add.add(call(H,"members","(Ljava/util/List;L"+PC+";)Ljava/util/List;"));m.instructions.insertBefore(previous(iterator),add);iterators++;m.instructions.insertBefore(v,new VarInsnNode(ALOAD,0));m.instructions.set(v,call(TARGET,"snapshots","(L"+PC+";L"+PC+";)Ljava/util/List;"));snapshots++;
   }
   for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode v&&v.owner.equals(PC)&&v.name.equals("sameClassicWorldMap")&&previous(v) instanceof VarInsnNode owner&&owner.var==9){m.instructions.set(v,call(TARGET,"same","(L"+PC+";L"+PC+";)Z"));gates++;}
  }if(roots!=2||snapshots!=2||iterators!=2||gates!=4)throw new AssertionError("exact two negative roots "+roots+" "+snapshots+" "+iterators+" "+gates);
 }
 public static void main(String[]args)throws Exception{try(var j=new JarFile(args[1])){for(var name:List.of(PC,NEG,P+"NativeWeaponBreakTargetLifecycle")){var c=read(j,name);patch(c);var expected=bytes(c);if(args[0].equals("splice")){var out=Path.of(args[2]).resolve(name+".class");Files.createDirectories(out.getParent());Files.write(out,expected);}else try(var candidate=new JarFile(args[2])){if(!Arrays.equals(expected,bytes(read(candidate,name))))throw new AssertionError(name);}}}System.out.println("PASS two negative roots/capture wrappers and speed packet actor fence; original player/BATTLE predicates and cost/probability/effect bodies preserved");}
}
